describe('File Upload Success Checkmark', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="file-input"]').should('be.visible');
  });

  it('should display success checkmark when file is fully uploaded', () => {
    const fileName = 'test-file.pdf';

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('file content'),
      fileName: fileName,
      mimeType: 'application/pdf'
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-progress"]', { timeout: 10000 }).should('exist');

    cy.get('[data-testid="success-checkmark"]', { timeout: 15000 })
      .should('be.visible')
      .and('have.class', 'checkmark-animated');

    cy.get('[data-testid="upload-status"]')
      .should('contain', 'Upload complete');

    cy.get('[data-testid="file-name"]')
      .should('contain', fileName);
  });

  it('should handle large file upload and display success checkmark', () => {
    const largeFileName = 'large-file.zip';
    const largeFileSize = 50 * 1024 * 1024;

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.alloc(largeFileSize),
      fileName: largeFileName,
      mimeType: 'application/zip'
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-progress"]').should('be.visible');

    cy.get('[data-testid="progress-percentage"]', { timeout: 30000 })
      .should('contain', '100');

    cy.get('[data-testid="success-checkmark"]', { timeout: 30000 })
      .should('be.visible')
      .and('have.attr', 'aria-label', 'Upload successful');

    cy.get('[data-testid="upload-status"]')
      .should('have.class', 'success')
      .and('contain', 'Upload complete');

    cy.get('[data-testid="file-size"]')
      .should('contain', '50 MB');
  });

  it('should display checkmark for multiple file uploads', () => {
    const files = ['file1.txt', 'file2.txt', 'file3.txt'];

    files.forEach((fileName) => {
      cy.get('[data-testid="file-input"]').selectFile({
        contents: Cypress.Buffer.from('test content'),
        fileName: fileName,
        mimeType: 'text/plain'
      });

      cy.get('[data-testid="upload-button"]').click();

      cy.get(`[data-testid="success-checkmark-${fileName}"]`, { timeout: 15000 })
        .should('be.visible');
    });

    cy.get('[data-testid="success-checkmark"]').should('have.length', 3);
  });

  it('should show checkmark with correct accessibility attributes', () => {
    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('accessible file'),
      fileName: 'accessible.pdf',
      mimeType: 'application/pdf'
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="success-checkmark"]', { timeout: 15000 })
      .should('have.attr', 'role', 'img')
      .and('have.attr', 'aria-label')
      .and('not.have.attr', 'aria-hidden', 'true');

    cy.get('[data-testid="upload-status"]')
      .should('have.attr', 'role', 'status')
      .and('contain', 'Upload complete');
  });

  it('should persist checkmark after page interaction', () => {
    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('persistent file'),
      fileName: 'persistent.pdf',
      mimeType: 'application/pdf'
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="success-checkmark"]', { timeout: 15000 })
      .should('be.visible');

    cy.get('[data-testid="upload-container"]').click();

    cy.get('[data-testid="success-checkmark"]')
      .should('still.be.visible');

    cy.get('[data-testid="close-button"]').should('be.visible').click();

    cy.get('[data-testid="success-checkmark"]')
      .should('not.exist');
  });
});
